import zipfile, pickle, io, struct, json, numpy as np

z = zipfile.ZipFile('model.pth')
prefix = 'simple_mnist'

DT = {'FloatStorage': np.float32, 'DoubleStorage': np.float64,
      'LongStorage': np.int64, 'HalfStorage': np.float16}

class Store:
    def __init__(self, key, dtype, numel):
        self.key, self.dtype, self.numel = key, dtype, numel
    def data(self):
        b = z.read(f'{prefix}/data/{self.key}')
        return np.frombuffer(b, dtype=self.dtype)

def rebuild(storage, offset, size, stride, req_grad, hooks, *a):
    arr = storage.data()
    n = int(np.prod(size)) if size else 1
    flat = arr[offset:offset+n]
    return flat.reshape(size)

class U(pickle.Unpickler):
    def find_class(self, mod, name):
        if mod == 'torch._utils' and name == '_rebuild_tensor_v2':
            return rebuild
        if mod == 'torch' and name.endswith('Storage'):
            return DT[name]
        if mod == 'collections' and name == 'OrderedDict':
            return dict
        raise Exception(mod+' '+name)
    def persistent_load(self, pid):
        typ, dtype, key, loc, numel = pid
        return Store(key, dtype, numel)

sd = U(io.BytesIO(z.read(f'{prefix}/data.pkl'))).load()
out = {}
for k, v in sd.items():
    print(k, v.shape, v.dtype)
    out[k] = np.asarray(v, dtype=np.float64).tolist()
json.dump(out, open('weights.json','w'))
