#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <cmath>
#include "lodepng.h"
extern "C" {
#include "cJSON.h"
}

static std::vector<double> flat(cJSON* n, std::vector<int>& shape, int depth = 0) {
    std::vector<double> out;
    if (cJSON_IsArray(n)) {
        int sz = cJSON_GetArraySize(n);
        if ((int)shape.size() <= depth) shape.push_back(sz);
        for (int i = 0; i < sz; i++) {
            std::vector<double> sub = flat(cJSON_GetArrayItem(n, i), shape, depth + 1);
            out.insert(out.end(), sub.begin(), sub.end());
        }
    } else if (cJSON_IsNumber(n)) {
        out.push_back(n->valuedouble);
    }
    return out;
}

struct Tensor { std::vector<double> v; std::vector<int> shape; };

static bool getTensor(cJSON* root, const char* name, Tensor& t) {
    cJSON* n = cJSON_GetObjectItemCaseSensitive(root, name);
    if (!n) return false;
    t.shape.clear();
    t.v = flat(n, t.shape);
    return true;
}

// y = W x + b, W is [out, in]
static std::vector<double> linear(const Tensor& W, const Tensor& b, const std::vector<double>& x) {
    int out = W.shape[0], in = W.shape[1];
    std::vector<double> y((size_t)out, 0.0);
    for (int o = 0; o < out; o++) {
        double s = b.v.empty() ? 0.0 : b.v[o];
        const double* w = &W.v[(size_t)o * in];
        for (int i = 0; i < in && i < (int)x.size(); i++) s += w[i] * x[i];
        y[o] = s;
    }
    return y;
}

static std::string readFile(const char* p) {
    FILE* f = fopen(p, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", p); exit(1); }
    std::string s;
    char buf[65536];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), f)) > 0) s.append(buf, n);
    fclose(f);
    return s;
}

int main(int argc, char** argv) {
    if (argc < 3) { fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]); return 1; }

    // ---- image ----
    std::vector<unsigned char> img;
    unsigned w = 0, h = 0;
    unsigned err = lodepng::decode(img, w, h, argv[2], LCT_GREY, 8);
    if (err) { fprintf(stderr, "png error %u: %s\n", err, lodepng_error_text(err)); return 1; }

    const int S = 28;
    std::vector<double> px((size_t)S * S, 0.0);
    for (int y = 0; y < S; y++) {
        for (int x = 0; x < S; x++) {
            // nearest-neighbour resample (identity when already 28x28)
            unsigned sy = (unsigned)((h == (unsigned)S) ? y : ((double)y * h) / S);
            unsigned sx = (unsigned)((w == (unsigned)S) ? x : ((double)x * w) / S);
            if (sy >= h) sy = h - 1;
            if (sx >= w) sx = w - 1;
            px[(size_t)y * S + x] = img[(size_t)sy * w + sx] / 255.0;
        }
    }

    // ---- weights ----
    std::string js = readFile(argv[1]);
    cJSON* root = cJSON_Parse(js.c_str());
    if (!root) { fprintf(stderr, "bad json\n"); return 1; }
    cJSON* sd = root;
    cJSON* nested = cJSON_GetObjectItemCaseSensitive(root, "state_dict");
    if (nested) sd = nested;

    const char* names[3][2] = {
        {"input_layer.weight", "input_layer.bias"},
        {"hidden_layer.weight", "hidden_layer.bias"},
        {"output_layer.weight", "output_layer.bias"},
    };

    std::vector<double> x = px;
    std::vector<double> out;
    for (int l = 0; l < 3; l++) {
        Tensor W, b;
        if (!getTensor(sd, names[l][0], W)) { fprintf(stderr, "missing %s\n", names[l][0]); return 1; }
        getTensor(sd, names[l][1], b);
        if (W.shape.size() < 2) { fprintf(stderr, "bad shape %s\n", names[l][0]); return 1; }
        out = linear(W, b, x);
        if (l < 2) for (size_t i = 0; i < out.size(); i++) if (out[i] < 0) out[i] = 0;  // ReLU
        x = out;
    }

    int best = 0;
    for (size_t i = 1; i < out.size(); i++) if (out[i] > out[best]) best = (int)i;
    printf("%d\n", best);
    cJSON_Delete(root);
    return 0;
}
